"""Prepare the original closure-report postimage and bind complete phase evidence."""
import hashlib,json,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[6]
ONTOLOGY=ROOT/'implementation/lab-ontology/candidates/v1'
CORE={'path':'implementation/lab-ontology/candidates/v1/receipts/coherence-closure.json','sha256':'516e726725bebd7a395d8495c295ab6fa901eb0d11c44ca3abe11fc42dcf89b8'}
def sha(raw):return hashlib.sha256(raw).hexdigest()
def bind(p):return {'path':p.relative_to(ROOT).as_posix(),'sha256':sha(p.read_bytes())}
def emit(p,v):
 p.parent.mkdir(parents=True,exist_ok=True)
 with p.open('x') as f:f.write(json.dumps(v,indent=2,sort_keys=True)+'\n')
def run(pin):
 selection=HERE/'selection.json';assert bind(selection)['sha256']==pin
 s=json.loads(selection.read_text());assert bind(HERE/'materialize.py')==s['producer_binding'] and s['authority_effect']=='none'
 core=ROOT/CORE['path'];assert bind(core)==CORE;v=json.loads(core.read_text());assert v['result']=='PASS' and v['task_complete'] and v['admitted_coherence'] is False
 for b in v['files']:
  p=ROOT/b['path'];assert sha(p.read_bytes())==b['sha256'],b['path']
 checks=v['tests']+len(v['join_checks'])+len(v['validation_checks'])
 target=HERE/'postimages/docs/migration-plans/lab-selected-slice/closure.md'
 text=f'''# Selected Lab ontology and migration candidate coherence\n\nStatus: candidate O07 coherence verified. Authority effect: none. Actual owner outcome: absent. Admitted operational coherence remains A03 after S02/R08/A01. This is a proposed documentation postimage; no canonical migration cutover is performed.\n\n## Actual reconstruction\n\nTwo independent fresh processes reconstructed all 225 original O05 package files, byte for byte, and all 220 schema-valid metadata carriers. They verified 88 semantic and 88 governance original event tuples plus native checkpoint parity. The absent historical native pathname was explicitly relocated to an independently pinned identical binary. Original scope/profile/code/event bytes were unchanged; owned stores and fixture keys were removed.\n\nTwo fresh diagnostics produced identical results for all 31 source/schema/Definition/endpoint/governance/adoption checks. Six fresh query processes reproduced all five written historical/current/native questions twice: ten byte-identical answers. Historical Project cursors 2/2, current Project cursors 5/5 and native ontology cursors 88/88 remain distinct. O03 governed genesis remains hash-sealed, with zero approval signatures or admission transactions. No derived cache or Session memory was restored as a replay source.\n\n## Selected source accounting\n\nThe 140 dispositions retain 88 adaptations, 43 references and nine blocked exact revisions. Twenty excluded packages and the independently observed deferred checkout/epoch remain explicit. The staged metadata comprises 131 Sources, 38 Source-representing OntologyNodes, 50 local OntologyEdges and one GeneratedOutput. Local interpretation retains twenty predicates, 49 directed connections and one symmetric connection; no global Typed Relation or source-domain instance is inferred. Every O06 metadata snapshot and all 88 separate adoption intents preserve their original digest and event bridges.\n\nA Product label on a represented Source is source-qualified metadata. Instance admission, source meaning, ontology adoption, lifecycle, evidence confidence, commitment, challenge state, current action authority and Session state are independent. Unknown confidence and exact challenge owner/resolution gates remain explicit. Historical D73 and current D75 retain their original missing revision/contract/signature/frontier gaps; current D75 still has 300 mapped and 185 unresolved subjects.\n\n## Evidence and remaining boundary\n\n{checks} recorded checks passed: {v['tests']} guards, {len(v['join_checks'])} joins and {len(v['validation_checks'])} final acceptance checks. All terminal observations and original file bindings are retained in the core proof receipt. The failed first relocation adapter is preserved; its successor uses class inheritance and passes the complete suite and both actual rebuilds.\n\nOriginal candidate owner refs are archived provenance. Eligible final owners, exact registry/carrier/native implementation/environment/entrypoint postimages and Decision cores remain S02 obligations; complete operator APIs/client/packaging/acceptance work continues. The one actual R08 response must bind the complete final selection. A01 applies accepted scopes only; A03 verifies admitted operation. Rejected/revised scope blocks dependent effects.\n\nNo canonical admission/adoption, original source execution/body import or export, current Lesson permission, source retirement, activation/cutover, human pilot, general effectiveness, stable release or complete-repository closure is claimed. Machine Agents remain ephemeral; Project State, Context View and Ontology View are durable context sources, and short memory belongs only to a Session.\n\nCore proof: {CORE['path']}\nSHA256: {CORE['sha256']}\n'''
 target.parent.mkdir(parents=True,exist_ok=True)
 with target.open('x') as f:f.write(text)
 rows=v['files']+[CORE,bind(selection),bind(HERE/'materialize.py'),bind(target)];unique={b['path']:b for b in rows}
 receipt={**v,'schema_version':'lab-O07-complete-candidate-closure/v1-candidate','core_proof_receipt_binding':CORE,'closure_report_postimage_binding':bind(target),
  'proposed_closure_report_destination':'docs/migration-plans/lab-selected-slice/closure.md','closure_report_is_canonical':False,
  'closure_report_producer_selection_binding':bind(selection),'files':list(sorted(unique.values(),key=lambda b:b['path']))}
 output=HERE/'receipts/0001.json';emit(output,receipt);print(json.dumps({'result':'PASS','recorded_checks':checks,'files':len(unique),'receipt_binding':bind(output),'closure_report_postimage_binding':bind(target)}))
if __name__=='__main__':run(sys.argv[1])
